  'client.calculation.holiday_pay.unit.calendar': 'calendaires',
  'client.calculation.methods.two_counts':
    'Les entreprises le calculent au prorata des jours calendaires ou des mois (mois entiers plus les jours du mois en cours / 30)\u00a0; les deux calculs sont indiqués.',
  'client.calculation.methods.three_counts':
    "Les entreprises le calculent au prorata des jours calendaires ou des mois (mois entiers plus les jours restants / 30), en comptant les mois selon le calendrier ou à partir de votre date d'entrée\u00a0; les trois calculs sont indiqués.",
