  'employment.tab.modalidad': 'Contrat',
  'employment.tab.salario': 'Salaire',
  'employment.tab.jornada': 'Temps de travail',
  'employment.tab.prueba': 'Conditions',
  'employment.tab.resultado': 'Résultat',
  'employment.choose': 'Choisissez une réponse',
  'employment.answer.yes': 'Oui',
