  'employment.answer.unknown': 'Je ne sais pas',
  'employment.rows.full': 'Vous avez atteint le nombre maximal de lignes de cette liste.',
  'employment.relation.question': 'Votre relation de travail',
  'employment.relation.help':
    "Cette vérification concerne la relation de travail de droit commun (relación laboral común) de l'Estatuto de los Trabajadores. Ces réponses vous diront si la vôtre en fait partie.",
  'employment.relation.kind': "Quelle relation avez-vous avec l'entreprise\u00a0?",
  'employment.relationship.common': 'Travail salarié',
  'employment.relationship.common_hint':
    "La relation de presque tout le monde\u00a0: vous travaillez pour une entreprise en échange d'un salaire.",
  'employment.relationship.household': 'Emploi de maison',
  'employment.relationship.household_hint': 'Vous travaillez chez un particulier.',
  'employment.relationship.senior_management': 'Cadre dirigeant (alta dirección)',
  'employment.relationship.senior_management_hint':
    "Vous dirigez l'entreprise avec des pouvoirs propres à son titulaire.",
  'employment.relationship.sport': 'Sport professionnel',
