  'employment.relationship.medical_resident': 'Internat en santé (residencia sanitaria)',
  'employment.relationship.medical_resident_hint': 'Vous faites votre internat (MIR, EIR, FIR…).',
  'employment.relationship.special_employment_centre':
    "Centre spécial d'emploi (centro especial de empleo)",
  'employment.relationship.special_employment_centre_hint':
    "Vous travaillez dans un centre spécial d'emploi avec un handicap reconnu.",
  'employment.relationship.public_servant': 'Fonction publique',
  'employment.relationship.public_servant_hint': 'Vous êtes fonctionnaire.',
  'employment.relationship.other_special': 'Autre relation spéciale',
  'employment.relationship.other_special_hint':
    'Par exemple, dockers, personnes détenues travaillant en établissement pénitentiaire ou représentants de commerce.',
  'employment.hiring.question': 'Votre embauche',
  'employment.relation.agency':
    'Votre contrat a-t-il été conclu avec une entreprise de travail temporaire pour travailler dans une autre\u00a0?',
  'employment.relation.agency_hint':
    "Une ETT qui vous met à disposition d'une entreprise utilisatrice.",
  'employment.relation.relief': "S'agit-il d'un contrat de relève (contrato de relevo)\u00a0?",
  'employment.relation.relief_hint':
    'Celui qui est conclu pour remplacer une personne qui part en retraite partielle.',
  'employment.relation.minor': 'Avez-vous moins de 18 ans\u00a0?',
  'employment.written.question': 'Votre âge et votre contrat',
  'employment.relation.written': 'Avez-vous votre contrat par écrit\u00a0?',
  'employment.relation.written_hint': "Un document avec votre nom et celui de l'entreprise.",
  'employment.dates.question': 'Dates du contrat',
  'employment.relation.start': 'Date de début',
  'employment.relation.start_hint': 'Le jour où vous avez commencé ou commencerez à travailler.',
  'employment.relation.end': 'Date de fin',
  'employment.relation.end_hint':
    "Si le contrat est à durée déterminée et l'indique. Sinon, laissez vide.",
  'employment.relation.signed': 'Date du contrat',
  'employment.relation.signed_hint':
    'Le jour où le contrat a été signé, si vous le savez. Sinon, laissez vide.',
  'employment.modality.question': 'Votre type de contrat',
  'employment.modality.help':
    'Il figure dans le titre du contrat ou dans sa première clause. Si un code apparaît sur vos bulletins de paie (100, 402, 410…), il aide aussi à le reconnaître.',
  'employment.modality.kind': "De quel type de contrat s'agit-il\u00a0?",
  'employment.modality.permanent_hint': 'Sans date de fin. Code 100 ou 200.',
  'employment.modality.discontinuous_hint':
    'À durée indéterminée, mais vous ne travaillez que par saisons ou par périodes. Code 300.',
  'employment.modality.production_hint':
    "À durée déterminée pour un surcroît de travail que l'effectif ne peut pas absorber. Code 402 ou 502.",
  'employment.modality.production_occasional_hint':
    'À durée déterminée pour des situations occasionnelles et prévisibles de courte durée, comme des campagnes.',
  'employment.modality.replacement_hint':
    'À durée déterminée pour remplacer une personne qui a le droit de retrouver son poste. Code 410 ou 510.',
  'employment.modality.replacement_selection_hint':
    'À durée déterminée pour pourvoir un poste pendant une procédure de recrutement.',
  'employment.modality.training_alternance_hint':
    'Travail et études en même temps, avec un plan de formation. Code 421.',
  'employment.modality.training_practice_hint':
    'Premier emploi après la fin des études, pour mettre en pratique ce qui a été appris. Code 420.',
  'employment.modality.work_or_service_hint':
    "Une appellation d'avant 2022. Si votre contrat l'utilise, cochez-la même s'il est récent.",
  'employment.modality.eventual_hint':
    "Une autre appellation d'avant 2022 pour le contrat pour circonstances de la production.",
  'employment.modality.interim_hint':
    "Une autre appellation d'avant 2022 pour le contrat de remplacement.",
  'employment.modality.unknown_hint':
    'En cas de doute, cochez cette option et le résultat le dira.',
  'employment.extensions.question': 'Les prolongations',
  'employment.modality.extensions': 'Nombre de prolongations (prórrogas)',
  'employment.modality.extensions_hint': 'Le nombre de fois où il a été prolongé. Si aucune, 0.',
  'employment.cause.question': 'Le motif du contrat',
  'employment.modality.cause': 'Le contrat explique-t-il le motif de sa durée déterminée\u00a0?',
  'employment.modality.cause_hint':
    "Ce qui s'est passé dans l'entreprise pour qu'elle ait besoin de ce contrat\u00a0: une commande, une campagne…",
  'employment.modality.circumstances':
    'Et explique-t-il les circonstances concrètes et leur lien avec la durée\u00a0?',
