  'mortgage.holder.purpose.business':
    "Un local, un entrepôt ou un autre bien d'une activité professionnelle",
  'mortgage.deed.question': "L'acte notarié",
  'mortgage.deed.on': "Date de l'acte",
  'mortgage.deed.on_hint': "Celle de l'acte du prêt signé devant le notaire.",
  'mortgage.deed.amount': 'Capital du prêt',
  'mortgage.deed.amount_hint': 'En euros. Si vous ne le savez pas, laissez vide.',
  'mortgage.deed.consumer':
    'Avez-vous souscrit le prêt immobilier en tant que particulier, pour votre logement\u00a0?',
  'mortgage.deed.consumer_hint':
    "Votre acte indique généralement à quoi sert le prêt. La répartition de la Cour suprême (Tribunal Supremo) ne concerne que la personne qui l'a souscrit en tant que particulier.",
  'mortgage.rate.question': "Le taux d'intérêt",
  'mortgage.rate.type': 'Quel type de taux\u00a0?',
  'mortgage.rate.type.fixed': 'Fixe',
  'mortgage.rate.type.variable': 'Variable',
  'mortgage.rate.type.mixed': 'Mixte',
  'mortgage.rate.revision': 'Tous les combien de mois le taux est révisé',
  'mortgage.rate.revision_hint': 'Généralement 6 ou 12. Si vous ne le savez pas, laissez vide.',
  'mortgage.rate.deed_percent_question': "L'indemnité de remboursement anticipé",
  'mortgage.rate.deed_percent_fixed': 'À taux fixe (%)',
  'mortgage.rate.deed_percent_variable': 'À taux variable (%)',
  'mortgage.rate.deed_percent_hint':
    "Facultatif. Dans l'acte, elle s'appelle souvent «compensación por desistimiento». Si vous ne la connaissez pas, laissez vide\u00a0: le plafond légal s'applique.",
  'mortgage.expenses_clause.question': 'La clause de frais',
  'mortgage.expenses_clause.present':
    'Votre acte contient-il une clause qui met les frais à la charge de la personne qui demande le prêt\u00a0?',
  'mortgage.expenses_clause.present_hint':
    "Elle figure généralement parmi les clauses financières, avec un titre comme «Gastos a cargo de la parte prestataria» (frais à la charge de l'emprunteur).",
  'mortgage.expenses_clause.present.present': 'Oui, il en contient une',
  'mortgage.expenses_clause.present.absent': "Non, il n'en contient pas",
