  'mortgage.floor.question': 'La clause plancher',
  'mortgage.floor.present':
    "Votre acte fixe-t-il un taux minimum, en dessous duquel l'intérêt ne descend pas\u00a0?",
  'mortgage.floor.percent': 'Taux minimum fixé',
  'mortgage.floor.percent_hint':
    "En %, par exemple 3. S'il indique seulement que l'intérêt ne sera jamais négatif, saisissez 0.",
